#!/usr/bin/env bash
# The raw-pointer ("native") bodies of abla/text, abla/json and abla/compression/gzip against their portable twins on generated bytes
# (#1139 area 7; tests/cases/native-twins/main.ab): built under each compile-time tier, the interpreter runs the portable bodies and the JIT and the
# program itself the native ones, and the three must agree. Usage: tools/test-native-twins.sh [compiler]
set -euo pipefail
compiler=${1:-build/ablac}
[[ $compiler == /* || $compiler != */* ]] || compiler="$PWD/$compiler"
root=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")/.." && pwd)
cd "$root"
out=build/native-twins
rm -rf "$out"
mkdir -p "$out"
for tier in interp jit; do
    ABLA_EVAL_STEP_LIMIT=4000000000 ABLA_COMPILE_EVAL=$tier "$compiler" build tests/cases/native-twins/main.ab -o "$out/twins-$tier" --fast --no-cache
    result=$("$root/tools/run-limited.sh" "$out/twins-$tier") || { echo "native-twins ($tier): $result" >&2; exit 1; }
    [[ $result == 'native-twins ok' ]] || { echo "native-twins ($tier): $result" >&2; exit 1; }
done
echo "native-twins ok: the native and portable bodies agree on generated text, JSON and gzip (interpreter and JIT tiers)"
